from datasets import load_from_disk
import numpy as np
from scipy.optimize import curve_fit, minimize
import collections, json
d = load_from_disk('/app/data')
data = list(d)
groups = collections.defaultdict(list)
for x in data:
    groups[x['group']].append(x)

def sigmoid(lf, A, k, x0, C):
    return -A/(1+np.exp(k*(lf-x0))) - C

results = {}
for g, items in groups.items():
    lf = np.array([it['log_flops'] for it in items])
    y = np.array([it['brier_score'] for it in items])
    best_rmse = 1e9
    best_p = None
    for A0 in [0.1, 0.5, 1.0, 2.0]:
        for k0 in [-5, -2, 1, 2, 5, 10]:
            for x00 in [-1, 0, 1, 2]:
                for C0 in [0.0, 0.1, 0.3, 0.5]:
                    try:
                        p, _ = curve_fit(sigmoid, lf, y, p0=[A0,k0,x00,C0], maxfev=5000)
                        pred = sigmoid(lf, *p)
                        r = np.sqrt(np.mean((pred-y)**2))
                        if r < best_rmse:
                            best_rmse = r
                            best_p = p
                    except Exception:
                        pass
    results[g] = (best_p.tolist(), best_rmse)
    print(f"{g}: A={best_p[0]:.5f}, k={best_p[1]:.5f}, x0={best_p[2]:.5f}, C={best_p[3]:.5f}, rmse={best_rmse:.5f}")
with open('/tmp/fits.json','w') as f:
    json.dump(results, f)
